function fedY25Results(d){
  const X=typeof DRR25!=="undefined"&&DRR25[d.id]; if(!X) return "";
  const pr=X.progs.filter(p=>p.p||p.a), sum=(L,k)=>L.reduce((t,p)=>t+p[k],0);
  const vc=(A,P)=>P?vplan("exp",(A-P)/P*100):"", cells=(P,A)=>`<td>${fB(P)}</td><td class="vcell ${vc(A,P)}">${fB(A)}</td><td class="vcell ${vc(A,P)}">${vsSgn(A-P,fB)}</td>`;
  const groups=[...new Set(pr.map(p=>p.cr||"Other"))];
  const progTbl=`<div class="sctwrap"><table class="sct fgrpt"><caption>FY 2025–26 · start-of-year budget and spending, grouped by core responsibility</caption><thead><tr><th scope="col">Program</th><th scope="col">Budget</th><th scope="col">Spent</th><th scope="col">Difference</th></tr></thead><tbody>${groups.map(g=>{const G=pr.filter(p=>(p.cr||"Other")===g);
      return `<tr class="fgh"><th scope="rowgroup" colspan="4">${fEsc(g)}</th></tr>${G.map(p=>`<tr><th scope="row" class="fgp">${fEsc(p.n)}</th>${cells(p.p,p.a)}</tr>`).join("")}<tr class="fgs"><th scope="row">Subtotal, ${fEsc(g)}</th>${cells(sum(G,"p"),sum(G,"a"))}</tr>`;}).join("")}
      <tr class="tot"><th scope="row">Total, all ${pr.length} programs</th>${cells(sum(pr,"p"),sum(pr,"a"))}</tr></tbody></table></div>
      <p class="note">Program totals come from the department's 2025–26 Departmental Results Report. The budget here is the Main Estimates; the open data does not include the department's reasons for each difference. See its 2025–26 Departmental Results Report.</p>`;
  const L=X.goals, ST={"met":["Met","g-d"],"not met":["Not met","g-b"],"to be achieved":["Due later","g-x"],"not available":["Not reported","g-n"],"":["No rating","g-n"]};
  const order=["met","not met","to be achieved","not available",""], cnt=order.map(k=>[k,L.filter(z=>z.s===k).length]).filter(x=>x[1]);
  const met=L.filter(z=>z.s==="met").length, nm=L.filter(z=>z.s==="not met").length;
  const gsum=L.length?`<div class="fgoal"><div class="fgoal-n"><b>${L.length}</b><span>goals for FY 2025–26</span></div>
       <div class="fgoal-r"><div class="fgoal-chips">${cnt.map(([k,n])=>`<span class="fgc"><span class="grade ${ST[k][1]}">${ST[k][0]}</span> <b>${n}</b></span>`).join("")}</div>
       <span class="dgrades" aria-hidden="true">${cnt.map(([k,n])=>`<i class="${ST[k][1]}" style="flex:${n}" title="${ST[k][0]}: ${n}"></i>`).join("")}</span></div></div>`:`<p class="note">The FY 2025–26 goals for this organization are not in the open data.</p>`;
  const areas=[...new Set(L.map(z=>z.act||"Other"))];
  const rows=areas.map(ar=>{const G=L.filter(z=>(z.act||"Other")===ar);return G.map((z,k)=>`<tr>${k?"":`<th scope="rowgroup" rowspan="${G.length}" class="farea">${fEsc(ar)}</th>`}<td class="fgd">${fEsc(z.i)}</td><td class="num">${z.t?fValU(z.t,fUnit(z.i)):'<span class="muted">—</span>'}${+z.by>2026?`<small>due ${fEsc(z.by)}</small>`:""}</td><td class="num">${z.r?fValU(z.r,fUnit(z.i)):'<span class="muted">—</span>'}</td><td><span class="grade ${ST[z.s]?ST[z.s][1]:"g-n"}">${ST[z.s]?ST[z.s][0]:fEsc(z.s)}</span></td></tr>`).join("");}).join("");
  const goalsHtml=gsum+(L.length?vRoll("Every goal, by program area",L.length+" goals · the target, the result and whether it was met",`<div class="sctwrap"><table class="sct fgoals"><caption>${L.length} goals · grouped by program area</caption><thead><tr><th scope="col">Program area</th><th scope="col">Goal</th><th scope="col" class="num">Target</th><th scope="col" class="num">Result</th><th scope="col">Status</th></tr></thead><tbody>${rows}</tbody></table></div>
      <div class="note"><b>The department grades itself.</b> Each department picks its own goals (performance indicators), sets its own targets and says whether it met them. Treasury Board publishes them as they are. <i>Due later</i> means the target date is after this year. A goal can appear under both a main area of work and a program.</div>
      <div class="src">Source: ${fA(DRR25_SRC)}</div>`):"");
  const H=X.h;
  const staff=`<div class="dsh-kpis k3">${[
     ["Programs · spent vs budget",fB(H[1]),fPill(H[1]>H[0]?"off":"ok",(H[1]>H[0]?"+":"−")+fB(Math.abs(H[1]-H[0]))+" vs "+fB(H[0])),"Total of the department's programs, from its 2025–26 Departmental Results Report",""],
     ["Staff",fN(H[3]),fPill("neu",fN(H[2])+" planned"),"Counted as full-time staff",""],
     ["Goals met",L.length?met+" of "+(met+nm):"—",fPill("neu",L.length?L.length+" goals in all":"Not in the open data"),"Goals with a result that was rated met or not met",""]].map(fCard).join("")}</div>`;
  return `<h4 class="fgrp">Results</h4>${staff}<div class="fstack">`+
    fRoll("P","bk","Programs","Budget and spending by program",fB(H[1])+" spent","",progTbl+`<div class="src">Source: ${fA(DRR25_SRC)}</div>`)+
    fRoll(`<svg viewBox="0 0 20 20" fill="none" stroke="currentColor" stroke-width="2"><circle cx="10" cy="10" r="7.5"/><circle cx="10" cy="10" r="4"/><circle cx="10" cy="10" r="1" fill="currentColor"/></svg>`,"bg","Goals and results",L.length?L.length+" goals the department set":"Not in the open data",met+nm?met+" of "+(met+nm)+" met":"—",met+nm?(met/(met+nm)>=.75?"dn":met/(met+nm)<.5?"up":"cau"):"",goalsHtml)+`</div>`;
}
